import{_ as a,o as e,c as r,a5 as i}from"./chunks/framework.BF53ZjCA.js";const _=JSON.parse('{"title":"原石规划与定向","description":"","frontmatter":{"title":"原石规划与定向","cutting":"rough-planning"},"headers":[],"relativePath":"zh/cutting/rough-planning.md","filePath":"zh/cutting/rough-planning.md","lastUpdated":1789155237000}'),n={name:"zh/cutting/rough-planning.md"};function l(d,t,o,h,s,c){return e(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="原石规划与定向" tabindex="-1">原石规划与定向 <a class="header-anchor" href="#原石规划与定向" aria-label="Permalink to &quot;原石规划与定向&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>切工不是从“选择一个漂亮轮廓”开始，而是先读懂原石：观察体色分布、裂隙、 包裹体、透明度、晶体方向与潜在光学效应，再在重量保留、视觉效果和耐久性之间 做出取舍。规划图应记录台面方向、预计轮廓、主要风险和允许的损耗范围。</p><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><ul><li>先观察再下料：清洁、测量并在不同光线与方向下检查原石，标记裂隙、包体和色带。</li><li>定向优先：有色带、猫眼、星光或变彩时，台面方向会直接影响颜色与现象的呈现。</li><li>取舍要透明：保留重量不等于保留价值；过度追重可能牺牲亮度、对称性或耐久性。</li><li>规划需留安全边界：尖角、薄腰棱、深裂隙和应力集中区域应在设计阶段避开或加固。</li><li>最终方案应能解释“为什么这样切”，而不只是记录成品的形状。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>切工</th><th>备注</th></tr></thead><tbody><tr><td>欧泊</td><td>台面朝向最强变彩区域</td><td>优先呈现变彩区域</td></tr><tr><td>星光蓝宝石</td><td>让弧顶对准交叉的丝状包体</td><td>使星线集中于弧顶</td></tr></tbody></table><p><em>详见<a href="./intro.html">切割总览</a>。</em></p>',8)])])}const p=a(n,[["render",l]]);export{_ as __pageData,p as default};
